#!/usr/bin/env bash
set -euo pipefail

ROOT="${1:-${PROJECT_ROOT:-.}}"
APP="$ROOT/memeflow-app"
[[ -d "$APP" ]] || APP="$ROOT"

INDEX="$APP/index.html"
V26="$APP/ai-nav-layout-v26.js"
V44="$APP/bottom-nav-flush-v44.js"
V51="$APP/native-ai-sheet-v51.js"

for f in "$INDEX" "$V26" "$V44" "$V51"; do
  [[ -f "$f" ]] || { echo "ERROR: missing $f"; exit 1; }
done

DIR="$APP/.memeflow-patches/floating-ai-home-clean-owner-v3"
mkdir -p "$DIR"
STAMP="$(date +%Y%m%d-%H%M%S)"

INDEX_BAK="$DIR/index.html.$STAMP.bak"
V26_BAK="$DIR/ai-nav-layout-v26.js.$STAMP.bak"
V44_BAK="$DIR/bottom-nav-flush-v44.js.$STAMP.bak"
V51_BAK="$DIR/native-ai-sheet-v51.js.$STAMP.bak"

INDEX_WORK="$DIR/index.html.$STAMP.work.html"
V26_WORK="$DIR/ai-nav-layout-v26.$STAMP.work.js"
V44_WORK="$DIR/bottom-nav-flush-v44.$STAMP.work.js"
V51_WORK="$DIR/native-ai-sheet-v51.$STAMP.work.js"
PY="$DIR/install.$STAMP.py"
REPORT="$DIR/report.$STAMP.txt"

cp "$INDEX" "$INDEX_BAK"
cp "$V26" "$V26_BAK"
cp "$V44" "$V44_BAK"
cp "$V51" "$V51_BAK"

cp "$INDEX" "$INDEX_WORK"
cp "$V26" "$V26_WORK"
cp "$V44" "$V44_WORK"
cp "$V51" "$V51_WORK"

rollback(){
  cp "$INDEX_BAK" "$INDEX" 2>/dev/null || true
  cp "$V26_BAK" "$V26" 2>/dev/null || true
  cp "$V44_BAK" "$V44" 2>/dev/null || true
  cp "$V51_BAK" "$V51" 2>/dev/null || true
  rm -f "$INDEX_WORK" "$V26_WORK" "$V44_WORK" "$V51_WORK" "$PY"
}

trap 'echo "ERROR: V3 failed; restoring exact pre-install files."; rollback' ERR

printf '%s' '' | base64 -d > "$PY"
python3 "$PY" "$INDEX_WORK" "$V26_WORK" "$V44_WORK" "$V51_WORK" | tee "$REPORT"

node --check "$V26_WORK" >/dev/null
node --check "$V44_WORK" >/dev/null
node --check "$V51_WORK" >/dev/null

grep -q '20260810-FA3' "$INDEX_WORK"
grep -q 'MF_FLOATING_AI_HOME_CLEAN_OWNER_V3' "$V26_WORK"
grep -q 'MF_FLOATING_AI_HOME_CLEAN_OWNER_V3' "$V44_WORK"
grep -q 'MF_FLOATING_AI_HOME_CLEAN_OWNER_V3' "$V51_WORK"

cp "$INDEX_WORK" "$INDEX"
cp "$V26_WORK" "$V26"
cp "$V44_WORK" "$V44"
cp "$V51_WORK" "$V51"

cat > "$DIR/latest-manifest.txt" <<EOF
INDEX=$INDEX
V26=$V26
V44=$V44
V51=$V51
INDEX_BACKUP=$INDEX_BAK
V26_BACKUP=$V26_BAK
V44_BACKUP=$V44_BAK
V51_BACKUP=$V51_BAK
REPORT=$REPORT
EOF

rm -f "$INDEX_WORK" "$V26_WORK" "$V44_WORK" "$V51_WORK" "$PY"
trap - ERR

echo
echo "OK: FLOATING AI + HOME CLEAN OWNER V3 installed."
echo "Safari cache keys were changed."
echo "Now Stop -> Run, CLOSE the old Safari tab, then open the app again."
